)A

insert into CHB_EQU_SUB (INDENTIFY_MARK, REGIST_BANK_CODE, SUBMIT_STATUS, ORG_INDENTIFY_MARK, IS_BELONG_BANK, THE_BANK_NAME, THE_BANK_CODE, HOLDER_MARK, HOLDER_REGION, HOLDER_TYPE, PERSONAL_IDENTIFY_TYPE, INSTITUTION_IDENTIFY_TYPE, OTHER_IDENTIFY_NAME, IDENTIFY_NUMBER, SPV_CAP_ACC_BANK, OTHER_CAP_ACC_BANK, SPV_REGIST_CODE, HOLDER_DATE, HOLDER_NAME, HOLDER_SEX, HOLDER_RISK_PREFER, HOLDER_CELLPHONE, HOLDER_TELEPHONE, HOLDER_EMAIL, TYPE, REMARK, SUBMIT_TIME, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, DEPT_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ,ORG_CODE, CREATE_DEPT,CHECK_SEQNO ) select A.* from (
select #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.bankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.submitStatus,jdbcType=VARCHAR} SUBMIT_STATUS, #{item.orgIndentifyMark,jdbcType=VARCHAR} ORG_INDENTIFY_MARK, #{item.isBelongBank,jdbcType=CHAR} IS_BELONG_BANK, #{item.theBankName,jdbcType=VARCHAR} THE_BANK_NAME, #{item.theBankCode,jdbcType=VARCHAR} THE_BANK_CODE, #{item.holderMark,jdbcType=CHAR} HOLDER_MARK, #{item.holderRegion,jdbcType=VARCHAR} HOLDER_REGION, #{item.holderType,jdbcType=CHAR} HOLDER_TYPE, #{item.personalIdentifyType,jdbcType=CHAR} PERSONAL_IDENTIFY_TYPE, #{item.institutionIdentifyType,jdbcType=VARCHAR} INSTITUTION_IDENTIFY_TYPE, #{item.otherIdentifyName,jdbcType=VARCHAR} OTHER_IDENTIFY_NAME, #{item.identifyNumber,jdbcType=VARCHAR} IDENTIFY_NUMBER, #{item.spvCapAccBank,jdbcType=VARCHAR} SPV_CAP_ACC_BANK, #{item.otherCapAccBank,jdbcType=VARCHAR} OTHER_CAP_ACC_BANK, #{item.spvRegistCode,jdbcType=VARCHAR} SPV_REGIST_CODE, #{item.holderDate,jdbcType=DATE} HOLDER_DATE, #{item.holderName,jdbcType=VARCHAR} HOLDER_NAME, #{item.holderSex,jdbcType=CHAR} HOLDER_SEX, #{item.holderRiskPrefer,jdbcType=VARCHAR} HOLDER_RISK_PREFER, #{item.holderCellphone,jdbcType=VARCHAR} HOLDER_CELLPHONE, #{item.holderTelephone,jdbcType=VARCHAR} HOLDER_TELEPHONE, #{item.holderEmail,jdbcType=VARCHAR} HOLDER_EMAIL, #{item.type,jdbcType=CHAR} TYPE, #{item.remark,jdbcType=VARCHAR} REMARK, null SUBMIT_TIME, #{item.chbSubmitDeadline,jdbcType=TIMESTAMP} CHB_SUBMIT_DEADLINE, #{item.submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, current timestamp UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, current timestamp CREATE_TIME, '' SUMIT_SEQ, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.checkSeqno,jdbcType=VARCHAR} CHECK_SEQNO from sysibm.sysdummy1
)A

mapper.select:
select INDENTIFY_MARK as indentifyMark, ORG_INDENTIFY_MARK as orgIndentifyMark, REGIST_BANK_CODE as bankCode, TRIM(IS_BELONG_BANK) as isBelongBank, THE_BANK_NAME as theBankName, THE_BANK_CODE as theBankCode, HOLDER_MARK as holderMark, HOLDER_REGION as holderRegion, HOLDER_TYPE as holderType, nvl(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) identifyType, PERSONAL_IDENTIFY_TYPE as personalIdentifyType, INSTITUTION_IDENTIFY_TYPE as institutionIdentifyType, nvl(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) as IDENTIFY_TYPE, OTHER_IDENTIFY_NAME as otherIdentifyName, IDENTIFY_NUMBER as identifyNumber, SPV_CAP_ACC_BANK as spvCapAccBank, OTHER_CAP_ACC_BANK as otherCapAccBank, SPV_REGIST_CODE as spvRegistCode, HOLDER_DATE holderDate, HOLDER_NAME holderName, HOLDER_SEX holderSex, HOLDER_RISK_PREFER as holderRiskPrefer, HOLDER_CELLPHONE as holderCellphone, HOLDER_TELEPHONE as holderTelephone, HOLDER_EMAIL as holderEmail, TYPE as type, REMARK, SUMIT_SEQ sumitSeq, SUBMIT_STATUS as submitStatus, SUBMIT_TIME as submitTime, CHB_SUBMIT_DEADLINE as chbSubmitDeadline, SUBMIT_DEADLINE as submitDeadline, STATUS as status, sub.UPDATE_TIME as updateTime, sub.ORG_CODE orgCode, status.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus from chb_equ_sub sub left join CHB_SUBMIT_STATUS status on sub.sumit_seq = status.seqno
sub.REGIST_BANK_CODE LIKE concat(concat('%',#{bankCode}),'%')
#{orgCode}
#{status}
#{holderType,jdbcType=VARCHAR}
AND sub.INDENTIFY_MARK LIKE concat(concat('%',#{indentifyMark}),'%')
#{personalIdentifyType}
#{institutionIdentifyType}
AND sub.HOLDER_NAME LIKE concat(concat('%',#{holderName}),'%')
AND sub.IDENTIFY_NUMBER LIKE concat(concat('%',#{identifyNumber}),'%')
AND sub.ORG_INDENTIFY_MARK LIKE concat(concat('%',#{orgIndentifyMark}),'%')
#{submitFeedbackStatus}
#{submitStatus}
AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDate}
AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') <=#{submitDateEnd}
AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') >= #{updateTime}
AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') <= #{updateTimeEnd}
AND sub.CHB_SUBMIT_DEADLINE >= to_date(to_char(#{submitDeadLineStart},'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd HH24:mi:ss')
AND sub.CHB_SUBMIT_DEADLINE <= to_date(to_char(#{submitDeadLineEnd},'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd HH24:mi:ss')
ORDER BY sub.UPDATE_TIME DESC, sub.INDENTIFY_MARK ASC

mapper.insert:
insert into CHB_SUBMIT_STATUS (SEQNO, SUBMIT_NUM, SUBMIT_TYPE, SUBMIT_FEEDBACK_STATUS, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME) select A.* from (
select #{item.seqno,jdbcType=VARCHAR} SEQNO, #{item.submitNum,jdbcType=DECIMAL} SUBMIT_NUM, #{item.submitType,jdbcType=VARCHAR} SUBMIT_TYPE, #{item.submitFeedbackStatus,jdbcType=VARCHAR} SUBMIT_FEEDBACK_STATUS, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME from sysibm.sysdummy1
)A

mapper.select:
select count(*) from CHB_EQU_HOLD T

	 	T.STATUS <> 'D'

		 AND T.INDENTIFY_MARK = #{IndentifyMark,jdbcType=VARCHAR}
